#!/usr/bin/env bash
# Verity v1.2.2 for macOS — Voice Studio type-check fixes
# The source ZIP is embedded below. Ollama model downloads, if any, are separate.
set -euo pipefail

say() { printf '\n[Verity] %s\n' "$*"; }
fail() { printf '\n[Verity] ERROR: %s\n' "$*" >&2; exit 1; }

launch=1
case "${1:-}" in
  '') ;;
  --no-launch) launch=0 ;;
  -h|--help)
    printf 'Verity macOS v1.2 installer\n\nUsage: bash install-verity.sh [--no-launch]\n\nInstalls Verity.app into ~/Applications.\nRequires macOS 13+ and Apple Swift/Xcode Command Line Tools.\nThe complete Verity source code is embedded in this file.\n'
    exit 0
    ;;
  *) fail "Unknown option: $1 (try --help)" ;;
esac

[[ "$(uname -s)" == 'Darwin' ]] || fail 'This installer runs on macOS only.'

if ! command -v sw_vers >/dev/null 2>&1; then fail 'Cannot determine macOS version.'; fi
mac_major="$(sw_vers -productVersion | cut -d. -f1)"
[[ "$mac_major" =~ ^[0-9]+$ ]] || fail 'Cannot parse macOS version.'
(( mac_major >= 13 )) || fail 'Verity requires macOS Ventura (13) or later.'

if ! command -v xcrun >/dev/null 2>&1 || ! xcrun --find swift >/dev/null 2>&1; then
  say 'Apple Xcode Command Line Tools are required to compile Verity.'
  say 'Running xcode-select --install; after the installation finishes, run this script again.'
  xcode-select --install || true
  exit 1
fi

for utility in awk tail base64 shasum unzip rsync ditto open; do
  command -v "$utility" >/dev/null 2>&1 || fail "Required macOS utility is missing: $utility"
done

say 'Starting Verity v1.2 installation (Voice Studio, no sudo required).' 
workspace="$(mktemp -d "${TMPDIR:-/tmp}"/verity-install.XXXXXXXX)" || fail 'Could not create temporary folder.'
cleanup() { rm -rf "$workspace"; }
trap cleanup EXIT

line="$(awk '/^__VERITY_PAYLOAD_BEGIN__$/ { print NR + 1; exit }' "$0")"
[[ -n "$line" ]] || fail 'The bundled source archive is missing.'
archive="$workspace/VerityMac.zip"
if ! tail -n "+$line" "$0" | base64 -D > "$archive"; then
  fail 'Could not unpack the embedded source archive.'
fi

expected='eb5a4857d8a641088b9364521f4714c711a0cd25773c2738c5050391bc20cb9c'
actual="$(shasum -a 256 "$archive" | awk '{print $1}')"
[[ "$actual" == "$expected" ]] || fail 'Installer source integrity check failed. Download the installer again.'

mkdir -p "$workspace/unpacked"
unzip -q "$archive" -d "$workspace/unpacked"
bundle="$workspace/unpacked/VerityMac"
[[ -f "$bundle/Package.swift" && -f "$bundle/build.command" ]] || fail 'Incomplete Verity source bundle.'

source_dir="$HOME/Library/Application Support/Verity/Source"
mkdir -p "$source_dir"
rsync -a "$bundle/" "$source_dir/"

# v1.2.2: repair Fish Audio free-model selection, actionable voice errors,
# and audible macOS fallback without changing the signed source archive.
command -v python3 >/dev/null 2>&1 || fail 'Python 3 is required to update Verity (install Xcode Command Line Tools).'
say 'Applying Verity v1.2.2 voice playback fix.'
curl --proto '=https' --tlsv1.2 --fail --silent --show-error --location --retry 2 \
  'https://raw.githubusercontent.com/celineasher/NewRepo/c1cd00c665c93c32a3554bed71d2b677501263f8/verity-mac/audio-hotfix-1.2.2.py' \
  -o "$workspace/audio-hotfix.py" || fail 'Could not download the v1.2.2 audio fix from GitHub.'
python3 "$workspace/audio-hotfix.py" "$source_dir" || fail 'Could not patch Swift voice sources; installation stopped safely.'

# Verity v1.2.1 hotfix: update source BEFORE invoking Swift.
# The bundled v1.2 source has a missing AVFoundation import and a large
# SwiftUI settings expression that can exceed the macOS compiler's type-check limit.
command -v python3 >/dev/null 2>&1 || fail 'python3 is needed for the v1.2.1 Swift source fix (install Xcode Command Line Tools).'
python3 - "$source_dir/Sources/Verity/Views.swift" <<'VERITY_SWIFT_FIX'
from pathlib import Path
import sys

path = Path(sys.argv[1])
src = path.read_text()
if 'import AVFoundation' not in src:
    src = src.replace('import AppKit\n', 'import AppKit\nimport AVFoundation\n', 1)

if 'private var voiceStudioTitleBar' not in src:
    section = src.index('struct SettingsView: View {')
    body_pos = src.index('    var body: some View {', section)
    original_body = src[body_pos:]
    head_start = original_body.index('            HStack {')
    head_end = original_body.index('            Divider()', head_start)
    mic_start = original_body.index('                    header("MICROPHONE CONTROL"')
    mic_end = original_body.index('                    Divider()', mic_start)
    speech_start = original_body.index('                    header("VERITY\'S SPEAKING VOICE"')
    speech_end = original_body.index('                    Divider()', speech_start)
    prefs_start = original_body.index('                    header("APP PREFERENCES"')
    prefs_end = original_body.index('                }\n                .padding(24)', prefs_start)

    sections = {
        "voiceStudioTitleBar": original_body[head_start:head_end],
        "voiceStudioMicSection": original_body[mic_start:mic_end],
        "voiceStudioSpeechSection": original_body[speech_start:speech_end],
        "voiceStudioPreferencesSection": original_body[prefs_start:prefs_end],
    }
    new_body = """    var body: some View {
        VStack(spacing: 0) {
            voiceStudioTitleBar
            Divider()
            ScrollView {
                VStack(alignment: .leading, spacing: 19) {
                    voiceStudioMicSection
                    Divider()
                    voiceStudioSpeechSection
                    Divider()
                    voiceStudioPreferencesSection
                }
                .padding(24)
            }
        }
        .frame(width: 630, height: 780)
        .background(Theme.background)
        .preferredColorScheme(.dark)
        .onAppear {
            wakeDraft = store.wakePhrase
            serverDraft = store.serverURL
            fishVoiceDraft = store.fishVoiceID
            store.refreshMicrophones()
        }
    }

"""
    for name, content in sections.items():
        new_body += f'    private var {name}: some View {{\n'
        if name == "voiceStudioTitleBar":
            new_body += content
        else:
            new_body += '        VStack(alignment: .leading, spacing: 19) {\n' + content + '        }\n'
        new_body += '    }\n\n'
    src = src[:body_pos] + new_body + '}\n'

path.write_text(src)
version_file = path.parent / 'Version.swift'
if version_file.exists():
    version_file.write_text(version_file.read_text().replace('"1.2.0"', '"1.2.1"'))
build_file = path.parents[2] / 'build.command'
if build_file.exists():
    build_file.write_text(build_file.read_text().replace('<string>1.2.0</string>', '<string>1.2.1</string>'))
print('[Verity] SwiftUI type-check and AVFoundation import fixes applied (v1.2.1).')
VERITY_SWIFT_FIX

# Verity 1.2.3 — apply verified wake-up greeting to the source BEFORE compilation.
# Handles source version skew safely; no external unified patch or rej files.
python3 - "$source_dir" <<'VERITY_WAKE123'
from pathlib import Path
import re, sys

base = Path(sys.argv[1])
voice_path = base / 'Sources/Verity/VoiceController.swift'
version_path = base / 'Sources/Verity/Version.swift'
build_path = base / 'build.command'
voice = voice_path.read_text()
old = '                return tail.trimmingCharacters(in: .whitespacesAndNewlines)'
new = '''                let command = tail.trimmingCharacters(in: .whitespacesAndNewlines.union(.punctuationCharacters))
                // A wake-up greeting is itself a request, even without a question.
                return command.isEmpty ? "Say hello to me briefly and ask how you can help." : command'''
if old in voice:
    voice_path.write_text(voice.replace(old, new, 1))
elif new not in voice:
    sys.exit('VoiceController.swift: unexpected wake-word source; update refused')

version = version_path.read_text()
version, n = re.subn(r'(static let current\s*=\s*)"[0-9]+(?:\.[0-9]+){1,2}"',
                      r'\g<1>"1.2.3"', version, count=1)
if n != 1:
    sys.exit('Version.swift: missing version marker')
version_path.write_text(version)

build = build_path.read_text()
build, n = re.subn(r'(<key>CFBundleShortVersionString</key><string>)[^<]+(</string>)',
                   r'\g<1>1.2.3\2', build, count=1)
if n != 1:
    sys.exit('build.command: missing version marker')
build_path.write_text(build)
print('[Verity] Verified v1.2.3 voice greeting and app version source')
VERITY_WAKE123

say 'Compiling the native macOS app using Swift. This may take a few minutes on the first build.'
if ! (cd "$source_dir" && VERITY_SKIP_LAUNCH=1 bash ./build.command); then
  fail 'The Swift build failed. Check the compiler errors above. Your previous app installation, if any, was not replaced.'
fi

built="$source_dir/dist/Verity.app"
[[ -f "$built/Contents/MacOS/Verity" ]] || fail 'Compiler finished without producing Verity.app.'

apps="$HOME/Applications"
destination="$apps/Verity.app"
mkdir -p "$apps"
if command -v pgrep >/dev/null 2>&1 && pgrep -x Verity >/dev/null 2>&1; then
  fail 'Verity is currently running. Quit it using its menu-bar icon, then rerun this installer. The newly built app is saved in the source folder.'
fi

staged="$apps/.Verity.install.$$.app"
backup="$apps/.Verity.backup.$$.app"
rm -rf "$staged"
if ! ditto "$built" "$staged"; then fail 'Could not stage Verity.app for installation.'; fi
if [[ -e "$destination" ]]; then
  [[ -d "$destination" ]] || fail 'The destination exists but is not an application folder.'
  mv "$destination" "$backup"
fi
if ! mv "$staged" "$destination"; then
  if [[ -d "$backup" ]]; then mv "$backup" "$destination"; fi
  fail 'Could not finish installing Verity.app.'
fi
if [[ -d "$backup" ]]; then rm -rf "$backup"; fi

say "Installed: $destination"
say "Editable source: $source_dir"

if ! curl -fsS --max-time 3 'http://127.0.0.1:11434/api/tags' >/dev/null 2>&1; then
  if [[ -d /Applications/Ollama.app || -d "$HOME/Applications/Ollama.app" ]]; then
    say 'Starting Ollama to enable AI chat…'
    open -a Ollama >/dev/null 2>&1 || true
  else
    say 'Ollama was not reachable. Open Ollama before chatting in Verity.'
    say 'If needed, install Ollama from https://ollama.com/download/mac'
  fi
fi
if command -v ollama >/dev/null 2>&1; then
  if ! ollama list 2>/dev/null | awk 'NR > 1 {found = 1} END {exit !found}'; then
    say 'No Ollama model detected. To download a small model later, run: ollama pull llama3.2:3b'
  fi
else
  say 'If you have no Ollama models, install one through the Ollama app or run: ollama pull llama3.2:3b'
fi

# Install a stable update launcher. Once the GitHub repository is published,
# this fetches the latest source and reinstalls Verity with one command.
mkdir -p "$HOME/bin"
cat > "$HOME/bin/verity-update" <<'VERITY_UPDATER'
#!/usr/bin/env bash
set -euo pipefail
source_dir="$HOME/Library/Application Support/Verity/Source"
[[ -f "$source_dir/install.sh" ]] || { echo 'Verity source is missing. Reinstall using install-verity-v1.2.sh.' >&2; exit 1; }
exec bash "$source_dir/install.sh" --github "$@"
VERITY_UPDATER
chmod +x "$HOME/bin/verity-update"
say 'Future GitHub updates: bash ~/bin/verity-update (after publishing the repo via publish-github.sh)'

if (( launch == 1 )); then
  say 'Launching Verity. Look for the smiley in your macOS menu bar.'
  open "$destination" || say 'App installed but could not open automatically. Try opening it from ~/Applications.'
fi

printf '\n[Verity] Finished. Voice features can be enabled in the Verity menu after granting macOS permissions.\n'
exit 0

